BEGIN TRANSACTION;
DROP TABLE IF EXISTS "DonneesSession";
CREATE TABLE IF NOT EXISTS "DonneesSession" (
	"IdSession"	INTEGER,
	"DateSession"	TEXT,
	"IdPartieJoueur01"	INTEGER,
	"IdPartieJoueur02"	INTEGER,
	"IdPartieJoueur03"	INTEGER,
	"IdPartieJoueur04"	INTEGER,
	"IdPartieJoueur05"	INTEGER,
	"IdPartieJoueur06"	INTEGER,
	"IdPartieJoueur07"	INTEGER,
	"IdPartieJoueur08"	INTEGER,
	"IdPartieJoueur09"	INTEGER
);
DROP TABLE IF EXISTS "DonneesParties";
CREATE TABLE IF NOT EXISTS "DonneesParties" (
	"IdSession"	INTEGER,
	"IdPartie"	INTEGER,
	"IdJoueur"	TEXT,
	"Tps"	REAL,
	"DTps"	INTEGER,
	"NbImp"	INTEGER,
	"Imp/s"	TEXT,
	"Cible"	TEXT,
	"NbPt"	TEXT,
	"Score"	INTEGER,
	"PtParImp"	TEXT,
	"Dist"	INTEGER,
	"dmoy"	REAL,
	"dmin"	INTEGER,
	"dMax"	INTEGER,
	"Force"	REAL,
	"FMoy"	REAL,
	"Fmin"	REAL,
	"FMax"	REAL,
	"NbHGG"	INTEGER,
	"NbHG"	INTEGER,
	"NbBGG"	INTEGER,
	"NbBG"	INTEGER,
	"NbBD"	INTEGER,
	"NbBDD"	INTEGER,
	"NbHD"	INTEGER,
	"NbHDD"	INTEGER,
	"NbHS"	INTEGER,
	"NbHaut"	INTEGER,
	"NbBas"	INTEGER,
	"NbExtG"	INTEGER,
	"NbExtD"	INTEGER,
	"NbCentreD"	INTEGER,
	"NbCentreG"	INTEGER,
	"NbGauche"	INTEGER,
	"NbDroite"	INTEGER,
	"pHGG"	REAL,
	"pHG"	REAL,
	"pBGG"	REAL,
	"pBG"	REAL,
	"pBD"	REAL,
	"pBDD"	REAL,
	"pHD"	REAL,
	"pHDD"	REAL,
	"pH"	REAL,
	"pB"	REAL,
	"pExtG"	REAL,
	"pCG"	REAL,
	"pCD"	REAL,
	"pExtD"	REAL,
	"pG"	REAL,
	"pD"	REAL
);
DROP TABLE IF EXISTS "Session";
CREATE TABLE IF NOT EXISTS "Session" (
	"IdSession"	INTEGER NOT NULL,
	"Date"	TEXT,
	"IdPartieJoueur01"	INTEGER,
	"IdPartieJoueur02"	INTEGER,
	"IdPartieJoueur03"	INTEGER,
	"IdPartieJoueur04"	INTEGER,
	"IdPartieJoueur05"	INTEGER,
	"IdPartieJoueur06"	INTEGER,
	"IdPartieJoueur07"	INTEGER,
	"IdPartieJoueur08"	INTEGER,
	"IdPartieJoueur09"	INTEGER,
	PRIMARY KEY("IdSession")
);
DROP TABLE IF EXISTS "ParametresPartie";
CREATE TABLE IF NOT EXISTS "ParametresPartie" (
	"IdPartie"	INTEGER NOT NULL,
	"DatePartie"	TEXT NOT NULL,
	"IdJoueur"	INTEGER NOT NULL,
	"DureePartie"	INTEGER NOT NULL,
	"DminPartie"	INTEGER,
	"c1Partie"	REAL,
	"c2Partie"	REAL
);
DROP TABLE IF EXISTS "Joueurs";
CREATE TABLE IF NOT EXISTS "Joueurs" (
	"IdJoueur"	INTEGER NOT NULL,
	"CodeJoueur"	TEXT NOT NULL,
	"NomJoueur"	TEXT NOT NULL,
	"PrenomJoueur"	TEXT DEFAULT 'PrenomJoueur',
	"DateNaissance"	TEXT DEFAULT 'JJ/MM/AAAA',
	"TelJoueur"	INTEGER,
	"MailJoueur"	TEXT DEFAULT 'Mail@Joeur.net',
	"OrigineCoordJoueur"	INTEGER DEFAULT 0,
	"ClubJoueur"	TEXT,
	"DateCreation"	TEXT NOT NULL DEFAULT 'JJ/MM/AAAA'
);
COMMIT;
